            clauses.append(clause)
    return random.choice(clauses)

def polynomial_ring(cnf):
    n = len(cnf[0])
    ring = [[0] * (n + 1) for _ in range(n + 1)]
    for clause in cnf:
        for i, lit in enumerate(clause):
            if lit > 0:
                ring[i][lit - 1] += 1
            else:
                ring[lit - 1][i] += 1
    return ring

